"""Four named source-camera actor construction at the pinned CPU profile.

Callers supply source-grounded static transforms for overview/approach/corner
and a relative driver transform. Real pixel coverage must be audited after run.
"""

from contextlib import contextmanager


SIZES = {"overview": (1920, 1080), "approach": (1280, 720),
         "reference_corner": (1280, 720), "driver_reference": (1280, 720)}


@contextmanager
def source_cameras(world, ego, transforms):
    if set(transforms) != set(SIZES):
        raise ValueError("All four named source-camera transforms required")
    sensors = {}
    try:
        for name, (width, height) in SIZES.items():
            blueprint = world.get_blueprint_library().find("sensor.camera.rgb")
            blueprint.set_attribute("image_size_x", str(width))
            blueprint.set_attribute("image_size_y", str(height))
            blueprint.set_attribute("fov", "90")
            blueprint.set_attribute("sensor_tick", "0.05")
            kwargs = {"attach_to": ego} if name == "driver_reference" else {}
            sensor = world.spawn_actor(blueprint, transforms[name], **kwargs)
            if sensor is None:
                raise ValueError("Native camera spawn failed: " + name)
            sensors[name] = sensor
        yield sensors
    finally:
        for sensor in reversed(list(sensors.values())):
            sensor.stop()
            sensor.destroy()

"""CPU checked one-way site and exact initial truck body-gap placement.

The road is authored OpenDRIVE. Actual blueprint width, body lengths, traffic,
motion, legal highway status and source pixels need Native/source review.
"""
from pathlib import Path
import hashlib
import math
import xml.etree.ElementTree as ET


def _repo_root():
    return next((parent for parent in Path(__file__).resolve().parents
                 if (parent / 'runtime/python/carla_sgg/actors.py').is_file()), None)


ROAD = Path(__file__).resolve().parent / 'native-map-plan/one-way-truck-road.xodr'
CLASS_MAP = _repo_root() / 'runtime/python/carla_sgg/actors.py' if _repo_root() else None
TRUCK_BLUEPRINTS = ('vehicle.carlamotors.european_hgv', 'vehicle.carlamotors.carlacola')
GAP_TARGETS_M = {'gap_below_500ft': 150.0, 'gap_at_500ft': 152.4,
                 'gap_above_500ft': 155.0}
LANE_WIDTH_M = 3.8
ROAD_LENGTH_M = 1200.0
EGO_S_M = 100.0
MIN_EDGE_MARGIN_M = 50.0


def sha(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def validate_site():
    road = ET.parse(ROAD).getroot()
    if road.tag != 'OpenDRIVE':
        raise ValueError('Wrong authored road document')
    roads = road.findall('road')
    if len(roads) != 1:
        raise ValueError('Expected exactly one authored road')
    r = roads[0]
    if r.get('id') != '149237' or float(r.get('length')) != ROAD_LENGTH_M:
        raise ValueError('Wrong authored truck road identity or length')
    geometry = r.find('planView/geometry')
    if geometry is None or geometry.find('line') is None or any(
            float(geometry.get(key)) != value for key, value in
            {'s': 0, 'x': 0, 'y': 0, 'hdg': 0, 'length': ROAD_LENGTH_M}.items()):
        raise ValueError('Truck site is not the sourced straight approach')
    sections = r.findall('lanes/laneSection')
    if len(sections) != 1 or float(sections[0].get('s')) != 0:
        raise ValueError('Truck site has unexpected lane sections')
    driving = sections[0].findall('.//lane[@type="driving"]')
    if len(driving) != 1 or driving[0].get('id') != '-1':
        raise ValueError('Truck site is not a single forward driving lane')
    width = driving[0].find('width')
    if width is None or any(float(width.get(key)) != value for key, value in
            {'sOffset': 0, 'a': LANE_WIDTH_M, 'b': 0, 'c': 0, 'd': 0}.items()):
        raise ValueError('Truck lane width changed')
    if CLASS_MAP is None:
        raise ValueError('Pinned truck class map missing')
    classifications = CLASS_MAP.read_text()
    for bp in TRUCK_BLUEPRINTS:
        if f"'{bp}': 'truck'" not in classifications:
            raise ValueError('Selected blueprint lacks pinned truck classification: ' + bp)
    return {'road_source': str(ROAD.relative_to(_repo_root())),
            'road_sha256': sha(ROAD), 'class_source': str(CLASS_MAP.relative_to(_repo_root())),
            'class_sha256': sha(CLASS_MAP), 'road_id': 149237, 'lane_id': -1,
            'lane_width_m': LANE_WIDTH_M, 'same_direction_lane_count': 1,
            'blueprint_ids': list(TRUCK_BLUEPRINTS)}


def initial_pair(gap_case, ego_half_length_m, lead_half_length_m):
    """Return road coordinates from realized body lengths; no assumed truck size."""
    validate_site()
    if gap_case not in GAP_TARGETS_M:
        raise ValueError('Unknown exact gap case')
    lengths = (ego_half_length_m, lead_half_length_m)
    if any(isinstance(x, bool) or not isinstance(x, (float, int)) or
           not math.isfinite(x) or x <= 0 for x in lengths):
        raise ValueError('Realized vehicle half lengths required')
    gap = GAP_TARGETS_M[gap_case]
    ego_x = EGO_S_M
    lead_x = ego_x + ego_half_length_m + gap + lead_half_length_m
    if ego_x - ego_half_length_m < MIN_EDGE_MARGIN_M or lead_x + lead_half_length_m > ROAD_LENGTH_M - MIN_EDGE_MARGIN_M:
        raise ValueError('Truck bodies exceed sourced straight approach margins')
    return {'ego_center_xy_m': [ego_x, -LANE_WIDTH_M / 2],
            'lead_center_xy_m': [lead_x, -LANE_WIDTH_M / 2],
            'heading_deg': 0.0, 'lane_forward_xy': [1.0, 0.0],
            'planned_initial_body_gap_m': gap,
            'gap_case': gap_case, 'actual_spawn_and_motion': 'unverified'}


def validate_motion_envelope(placement, lead_half_length_m, speed_mps=12.0, duration_s=45.0):
    """Check a straight-road engineering travel budget, not realized motion."""
    if any(type(x) not in (int, float) or not math.isfinite(x) or x <= 0
           for x in (lead_half_length_m, speed_mps, duration_s)):
        raise ValueError('Invalid motion envelope values')
    endpoint = placement['lead_center_xy_m'][0] + speed_mps * duration_s + lead_half_length_m
    if endpoint > ROAD_LENGTH_M - MIN_EDGE_MARGIN_M:
        raise ValueError('Lead motion budget exceeds authored road')
    return {'projected_lead_front_at_end_m': endpoint,
            'remaining_margin_m': ROAD_LENGTH_M - endpoint,
            'assumes_constant_target_speed': True, 'actual_motion': 'unverified'}


if __name__ == '__main__':
    import json
    import sys
    if len(sys.argv) != 2:
        raise SystemExit('usage: truck_site.py OUTPUT_JSON')
    cases = {name: initial_pair(name, 5.0, 5.0) for name in GAP_TARGETS_M}
    proof = {'format': 'worker-truck-site-cpu-proof', 'site': validate_site(),
             'cases': cases,
             'motion_envelopes': {name: validate_motion_envelope(case, 5.0) for name, case in cases.items()},
             'sample_half_lengths_m': {'ego': 5.0, 'lead': 5.0},
             'sample_lengths_are_realized_dimensions': False,
             'physical_acceptance': False}
    Path(sys.argv[1]).write_text(json.dumps(proof, indent=2) + '\n')

"""Authored one-forward, one-opposing-lane passing site."""
import hashlib
from pathlib import Path
import xml.etree.ElementTree as ET

ROAD = Path(__file__).resolve().parent/'native-map-plan/overtaking-truck-road.xodr'


def validate_site():
    root = ET.parse(ROAD).getroot()
    roads = root.findall('road')
    if root.tag != 'OpenDRIVE' or len(roads) != 1:
        raise ValueError('Wrong overtaking road document')
    road = roads[0]
    if road.get('id') != '149239' or float(road.get('length', 'nan')) != 1200:
        raise ValueError('Wrong overtaking road identity or length')
    geometry = road.find('planView/geometry')
    if geometry is None or geometry.find('line') is None or any(
            float(geometry.get(key, 'nan')) != value for key, value in
            {'s': 0, 'x': 0, 'y': 0, 'hdg': 0, 'length': 1200}.items()):
        raise ValueError('Overtaking site is not straight')
    sections = road.findall('lanes/laneSection')
    if len(sections) != 1 or float(sections[0].get('s', 'nan')) != 0:
        raise ValueError('Unexpected overtaking lane sections')
    lanes = {int(lane.get('id')): lane for lane in sections[0].findall('.//lane[@type="driving"]')}
    if set(lanes) != {-1, 1}:
        raise ValueError('Overtaking needs one forward and one opposing lane')
    for lane in lanes.values():
        width = lane.find('width')
        if width is None or any(float(width.get(key, 'nan')) != value for key, value in
                {'sOffset': 0, 'a': 3.8, 'b': 0, 'c': 0, 'd': 0}.items()):
            raise ValueError('Overtaking lane width differs')
    return {'road_source': str(ROAD), 'road_sha256': hashlib.sha256(ROAD.read_bytes()).hexdigest(),
            'road_id': 149239, 'lane_id': -1, 'passing_lane_id': 1,
            'same_direction_lane_count': 1, 'lane_width_m': 3.8}

"""Native pair placement for the two available same-direction lanes case."""
from contextlib import contextmanager
import math

from truck_construction import _position,_projected_half_length,_width
from truck_site import TRUCK_BLUEPRINTS
from two_lane_site import validate_site

MIN_WIDTH_M=80*.0254


@contextmanager
def spawn_two_lane_pair(world,ego_blueprint,lead_blueprint,transform_at,
                        *,gap_tolerance_m=.05):
    site=validate_site()
    ids=[getattr(bp,'id',bp) for bp in (ego_blueprint,lead_blueprint)]
    if any(identifier not in TRUCK_BLUEPRINTS for identifier in ids):
        raise ValueError('Two-lane pair lacks pinned truck classification')
    actors=[];lane_y=-site['lane_width_m']/2
    try:
        for blueprint,x in ((ego_blueprint,100.0),(lead_blueprint,600.0)):
            actor=world.try_spawn_actor(blueprint,transform_at(x,lane_y,0.0))
            if actor is None:raise ValueError('Two-lane truck staging spawn failed')
            actors.append(actor)
        ego,lead=actors
        if any(_width(actor)<MIN_WIDTH_M for actor in actors):
            raise ValueError('Two-lane truck width below 80 inches')
        ego_half=_projected_half_length(ego,(1,0));lead_half=_projected_half_length(lead,(1,0))
        lead_x=_position(ego,(1,0))+ego_half+150.0+lead_half
        if lead_x+lead_half>1150:raise ValueError('Two-lane body exceeds road travel margin')
        lead.set_transform(transform_at(lead_x,lane_y,0.0));world.tick()
        for actor in actors:
            waypoint=world.get_map().get_waypoint(actor.get_location(),project_to_road=False)
            if waypoint is None or (waypoint.road_id,waypoint.lane_id)!=(site['road_id'],site['following_lane_id']):
                raise ValueError('Two-lane pair left sourced following lane')
        actual=(_position(lead,(1,0))-_projected_half_length(lead,(1,0))
                -_position(ego,(1,0))-_projected_half_length(ego,(1,0)))
        if not math.isclose(actual,150.0,abs_tol=gap_tolerance_m):
            raise ValueError('Two-lane pair missed fixed body-gap target')
        yield {'ego':ego,'lead':lead,'site':dict(site,lane_id=site['following_lane_id']),
               'initial_body_gap_m':actual,
               'realized_widths_m':{'ego':_width(ego),'lead':_width(lead)},
               'physical_motion':'unverified'}
    finally:
        for actor in reversed(actors):actor.destroy()

"""Retain original Native truck bodies, widths and frame identities at capture."""
import json
import math


def _finite_vector(values, label):
    result = [float(value) for value in values]
    if any(not math.isfinite(value) for value in result):
        raise ValueError('Nonfinite Native ' + label)
    return result


def _actor(actor, waypoint):
    bounds = actor.bounding_box
    vertices = bounds.get_world_vertices(actor.get_transform())
    if len(vertices) < 4:
        raise ValueError('Missing original complete truck body')
    body = [_finite_vector((v.x, v.y), 'truck body') for v in vertices]
    width = 2.0 * float(bounds.extent.y)
    if not math.isfinite(width) or width <= 0:
        raise ValueError('Missing realized truck width')
    return {'actor_id': actor.id, 'blueprint_id': actor.type_id,
            'road_id': waypoint.road_id, 'lane_id': waypoint.lane_id,
            'overall_width_m': width, 'overall_width_source': 'Native bounding_box; single vehicle only',
            'is_truck_or_combination': actor.type_id in ('vehicle.carlamotors.european_hgv',
                                                         'vehicle.carlamotors.carlacola'),
            'body_vertices_xy_m': body,
            'velocity_mps': _finite_vector((actor.get_velocity().x, actor.get_velocity().y,
                                           actor.get_velocity().z), 'truck velocity')}


def record_sample(frame_map, history_stream, snapshot, ego, lead, ego_waypoint, lead_waypoint):
    if ego_waypoint is None or lead_waypoint is None:
        raise ValueError('Missing original truck lane readback')
    frame, time_s = snapshot.frame, snapshot.timestamp.elapsed_seconds
    row = {'frame': frame, 'time_s': time_s, 'ego': _actor(ego, ego_waypoint),
           'lead': _actor(lead, lead_waypoint)}
    mapping = frame_map.append(frame, time_s)
    history_stream.write(json.dumps(row, allow_nan=False) + '\n')
    return {'video_frame': mapping['video_frame'], 'frame': frame}

"""Source-bound geometric observations for NRS 484B.127(2).

Widths and longitudinal body gap are measured in metres. The statutory 80 inch
and 500 foot values are reported exactly; conditions-permit, safe occupancy and
the legal overtaking exception remain review questions.
"""

import hashlib
import json
import math
from pathlib import Path


MIN_WIDTH_M = 80 * 0.0254
REQUIRED_GAP_M = 500 * 0.3048
REQUIRED = ("truck_history.jsonl", "road_context.json", "video_frames.jsonl")


def _finite(value, label):
    if isinstance(value, bool) or not isinstance(value, (int, float)) or not math.isfinite(value):
        raise ValueError("Missing finite " + label)
    return float(value)


def _rows(path):
    return [json.loads(line) for line in path.read_text().splitlines() if line.strip()]


def _body_span(actor, label):
    vertices = actor.get("body_vertices_xy_m")
    if not isinstance(vertices, list) or len(vertices) < 4:
        raise ValueError("Missing body vertices: " + label)
    projected = []
    for vertex in vertices:
        if not isinstance(vertex, list) or len(vertex) != 2:
            raise ValueError("Invalid body vertex: " + label)
        projected.append(tuple(_finite(v, "body vertex") for v in vertex))
    return projected


def analyze(root: Path) -> dict:
    root = Path(root)
    hashes = {}
    for name in REQUIRED:
        path = root / name
        if not path.is_file():
            raise ValueError("Missing required source: " + name)
        hashes[name] = hashlib.sha256(path.read_bytes()).hexdigest()
    context = json.loads((root / "road_context.json").read_text())
    for key in ("native_map_id", "road_id", "lane_id", "same_direction_lane_count",
                "lane_forward_xy", "lane_count_source"):
        if key not in context:
            raise ValueError("Missing Native road context: " + key)
    count = context["same_direction_lane_count"]
    if type(count) is not int or count < 1:
        raise ValueError("Invalid same-direction lane count")
    passing_lane = context.get('passing_lane_id')
    if passing_lane is not None and (type(passing_lane) is not int or passing_lane == context['lane_id'] or count != 1):
        raise ValueError('Invalid opposing passing lane context')
    tangent = context["lane_forward_xy"]
    if not isinstance(tangent, list) or len(tangent) != 2:
        raise ValueError("Missing lane tangent")
    tx, ty = (_finite(value, "lane tangent") for value in tangent)
    norm = math.hypot(tx, ty)
    if norm <= 0:
        raise ValueError("Zero lane tangent")
    tx, ty = tx / norm, ty / norm
    rows, frames = _rows(root / "truck_history.jsonl"), _rows(root / "video_frames.jsonl")
    if not rows or len(rows) != len(frames):
        raise ValueError("Incomplete history/frame map")
    samples, previous = [], (-1, -math.inf)
    for index, (row, frame) in enumerate(zip(rows, frames)):
        frame_id, time = row.get("frame"), row.get("time_s")
        time = _finite(time, "time")
        if type(frame_id) is not int or frame_id <= previous[0] or time <= previous[1]:
            raise ValueError("Nonmonotone original history")
        previous = (frame_id, time)
        if frame.get("video_frame") != index or frame.get("carla_frame") != frame_id or frame.get("time_s") != time:
            raise ValueError("Original video frame join failed")
        participants = {}
        for name in ("ego", "lead"):
            actor = row.get(name)
            allowed = {context['lane_id'], passing_lane} if name == 'ego' and passing_lane is not None else {context['lane_id']}
            if not isinstance(actor, dict) or actor.get("road_id") != context["road_id"] or actor.get("lane_id") not in allowed:
                raise ValueError("Participant not in sourced following lane: " + name)
            width = _finite(actor.get("overall_width_m"), "overall width")
            points = _body_span(actor, name)
            along = [x * tx + y * ty for x, y in points]
            participants[name] = {"width_m": width, "length_interval_m": [min(along), max(along)],
                                  "is_truck_or_combination": actor.get("is_truck_or_combination") is True,
                                  "lane_id": actor['lane_id']}
        gap = participants["lead"]["length_interval_m"][0] - participants["ego"]["length_interval_m"][1]
        samples.append({"frame": frame_id, "time_s": time, "longitudinal_body_gap_m": gap,
                        "ego_behind_lead": gap >= 0,
                        "ego": participants["ego"], "lead": participants["lead"]})
    return {"format": "worker-truck-following-observations", "sources": hashes,
            "native_road_context": context, "minimum_qualifying_width_m": MIN_WIDTH_M,
            "statutory_space_m": REQUIRED_GAP_M, "samples": samples,
            "same_direction_two_lane_exemption_observed": count >= 2,
            "conditions_permit_judgment": "unresolved", "safe_overtaker_occupancy_judgment": "unresolved",
            "legal_conclusion": "unresolved"}
